// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an actor and an amount to send to `receive()`
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a wide, admissible domain: allow zero and large values but bound to available balance range
        amount = bound(amount, 0, 1 ether);
        // ensure sender is not the zero address (EOA) to be a valid caller; keep wide
        vm.assume(sender != address(0));

        // fund the sender so it can send ether
        vm.deal(sender, amount);

        // call receive() via a payable plain transfer from sender
        bool ok;
        vm.startPrank(sender);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property (single assertion): if the call succeeded, depositsCount must have increased by exactly 1
        // Read depositsCount via the public getter
        uint256 d = c.depositsCount();
        // If the call succeeded, d == 1 (since c was just deployed with depositsCount == 0)
        // If the call reverted, ok == false and we don't require d changed.
        assertTrue(ok ? (d == 1) : (d == 0));
    }
}

