    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor and amount in wide admissible domain
        vm.assume(depositor != address(0));
        // bound amount to something reasonable to allow vm.deal
        amount = bound(amount, 0, 1 ether);

        // ensure depositor has the funds to send
        vm.deal(depositor, amount);

        bool ok;
        // perform the payable call into C.receive()
        vm.prank(depositor);
        try c.call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract accepts any deposit (including zero) without revert when called via receive()
        // and increments depositsCount; the mutant with inverted comparison will revert for any deposit.
        // Assert that the call did NOT revert on the reference implementation for these inputs.
        assertTrue(ok);
    }
}

