pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: an arbitrary sender and an amount of ether to send
    function testFuzz_property(address sender, uint256 amount) public {
        // Keep amount in a wide admissible domain but allow 0 too (0-value deposits are allowed by receive but here we care nonzero as the meaningful case);
        // Bound to something reasonable to avoid overflow in the test environment
        amount = bound(amount, 0, 1 ether);

        // Ensure sender has funds to send
        vm.deal(sender, amount);

        // Record depositsCount before
        uint before = c.depositsCount();

        // Try sending amount from sender to c using plain transfer via low-level call to trigger receive()
        bool ok;
        vm.prank(sender);
        // Use address(c).call to ensure low-level call to receive is performed
        try address(c).call{value: amount}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: whenever the receive call succeeded (ok == true), depositsCount increased by exactly 1.
        // This holds for the reference contract for all inputs; the mutant causes receive to revert for some inputs so ok==false there,
        // and thus will violate the universal acceptance behavior (some inputs do not result in ok==true and increment).
        if (ok) {
            assertTrue(c.depositsCount() == before + 1);
        } else {
            // If the receive reverted, then it's allowed that depositsCount did not increase; still assert consistency: depositsCount unchanged
            assertTrue(c.depositsCount() == before);
        }
    }
}

