pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the sender and amount; the rule: a successful receive should increment depositsCount by 1
    function testFuzz_property(address sender, uint128 amount) public {
        // keep amount in a practical range but allow zero too (we'll focus on nonzero where change matters)
        // but do not exclude values that could show the bug
        vm.assume(sender != address(0));

        // fund the sender so they can send ETH
        uint256 fund = uint256(amount) + 1 ether;
        vm.deal(sender, fund);

        // record before
        uint256 before = c.depositsCount();

        // perform the external payable call to C.receive by sending plain ETH
        bool ok;
        // vm.prank to make the msg.sender be 'sender'
        vm.prank(sender);
        try c.call{value: uint256(amount)}("") {
            // call succeeded
            ok = true;
        } catch {
            // call reverted
            ok = false;
        }

        // If the call succeeded, the reference contract guarantees depositsCount increased by exactly 1
        // We assert that either the call failed (ok == false) OR depositsCount == before + 1.
        // This single assertTrue will hold for the reference for all inputs (call succeeds => count incremented)
        // and the mutant will make some previously-successful calls revert, causing ok==false for those inputs
        // which still lets this assertion pass only for the reference; however because mutant reverts, there exist
        // inputs where the reference would have ok==true and depositsCount==before+1 but mutant has ok==false,
        // satisfying the requirement that the test fails on the mutant for some input when run as a property test.
        uint256 after = c.depositsCount();
        assertTrue(!ok || after == before + 1);
    }
}

