pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount; for very large amounts the unchecked increment could wrap
    function testFuzz_property(uint256 amt) public {
        // keep amt within payable limits but wide: at least 1 wei and at most the max uint256
        vm.assume(amt > 0);
        // fund a sender with amt
        address sender = address(0xBEEF);
        vm.deal(sender, amt);
        // perform the payable receive call from sender sending amt
        vm.prank(sender);
        // call receive by sending value
        (bool ok, ) = address(c).call{value: amt}("");
        // After the call, the reference ensures that depositsCount increment did not wrap:
        // i.e., depositsCount >= 1 (since it started at 0) whenever the receive succeeded
        // We assert that if the call succeeded, depositsCount >= 1. This property holds for the reference
        // but can be violated by the mutant which increments unguarded and may wrap to 0 for some amt.
        if (ok) {
            uint256 got = c.depositsCount();
            assertTrue(got >= 1);
        } else {
            // if call reverted, still assert true on a harmless tautology that reads c: require false would fail
            // but we must have exactly one assertTrue; so convert revert into an assertion about depositsCount == 0
            // (reference: if receive reverts then depositsCount stays 0). We allow either branch; keep single assertTrue
            // To satisfy single assertTrue requirement, map ok to the property: ok implies depositsCount>=1
            // Implemented above; here we simply assert that if !ok then depositsCount == 0
            uint256 got = c.depositsCount();
            assertTrue(ok || got == 0);
        }
    }
}

