pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the deposit value; the fuzzer will attempt large values that cause wrapping in the mutant
    function testFuzz_property(uint256 deposit) public {
        // Keep domain wide but ensure we send some value (including zero allowed).
        // No tight vm.assume so fuzzer can reach values that trigger overflow in mutant.

        // fund the sender so the payable call can succeed when allowed
        vm.deal(address(this), deposit);

        // record old depositsCount
        uint256 before = c.depositsCount();

        // perform the payable low-level call that invokes receive()
        // use try/catch to observe whether the call succeeded; reference should only succeed when invariant holds
        bool ok;
        (bool success, ) = address(c).call{value: deposit}("");
        ok = success;

        uint256 after = c.depositsCount();

        // General rule (single assertion): If the receive call succeeded then depositsCount == before + 1
        // This is satisfied by the reference for all inputs; the mutant (which increments unconditionally) will
        // allow an overflow case where after != before + 1 for some fuzzed deposit, causing this assertion to fail.
        assertTrue(!ok || after == before + 1);
    }
}

