pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender address and the amount of ETH sent
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender as a non-zero address (EOA or contract is fine); allow wide amount
        vm.assume(sender != address(0));
        // Fund the sender so they can send `amount` (if amount is 0 this is fine)
        uint256 fund = amount;
        // If amount is extremely large, cap funding to max uint256 to avoid vm.deal overflow
        if (fund > type(uint256).max) fund = type(uint256).max;
        // vm.deal expects uint256 for balance and an address; cap to a reasonable max (but keep wide)
        uint256 cap = 2**160 - 1;
        if (fund > cap) fund = cap;
        vm.deal(sender, fund);

        // read pre-state
        uint256 before = c.depositsCount();

        // perform the payable receive via a direct low-level call from the fuzzed sender
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");

        // read post-state
        uint256 after = c.depositsCount();

        // GENERAL ASSERTION: reference C never causes depositsCount to wrap-down on a single receive call.
        // So for ALL admissible inputs, after >= before.
        // This will hold on the reference contract for every input, but the mutant that removes the require
        // can allow wrapping so after < before for some fuzzed (sender, amount).
        assertTrue(after >= before);
    }
}

