pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz over an actor and an amount. The rule: if depositsCount was > 0 before receive, then after a subsequent receive (with any nonzero value) it must remain > 0.
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep admissible domain wide but ensure amount is a nonzero smallish value to transfer and actor is not zero address
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e18); // allow wide range but nonzero

        // Give actor some ETH and have them call receive once to potentially set depositsCount > 0
        vm.deal(actor, amount);
        vm.prank(actor);
        // first receive call
        (bool s1,) = address(c).call{value: amount}("\x00");
        // If the call failed for this actor/amount, we treat it as outside admissible domain and skip by assuming success
        vm.assume(s1);

        // Read depositsCount after first receive; require it to be > 0 to make the property meaningful
        uint256 before = c.depositsCount();
        vm.assume(before > 0);

        // Now perform a second receive (the deciding action) from the same actor with some nonzero amount
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool s2,) = address(c).call{value: amount}("");
        vm.assume(s2);

        // After the second receive, depositsCount must remain > 0 for the correct contract
        uint256 after = c.depositsCount();

        // Single assertion reading c's public getter: the contract must not have cleared a previously positive depositsCount to zero
        assertTrue(after > 0);
    }
}

