pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an actor address and an amount to send
    // General rule: for ANY caller and ANY payable amount, receive() increments depositsCount by exactly 1
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor admissible (non-zero) to be realistic; allow zero address too because reference should still hold
        // bound amount to a reasonable range so vm.deal can set balance (keep wide)
        amount = bound(amount, 0, 1 ether);

        // ensure actor has enough ETH to send
        vm.deal(actor, amount);

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // have actor call receive with value `amount`
        vm.prank(actor);
        // perform the payable call to trigger receive
        // using low-level call syntax via the contract's payable fallback (send ETH directly)
        // In Solidity test we can use: payable(address(c)).call{value: amount}("");
        // But per rules we must drive c through `receive` — using address(c).call triggers receive when empty calldata
        (bool ok, ) = payable(address(c)).call{value: amount}("\x00");
        // Some fuzzed actors may be contracts with no code in the test environment; that's fine.
        // The reference C will accept the call and increment depositsCount by 1 for any successful call.
        // We require the call itself to succeed so we only assert the increment when the call succeeded.
        if (!ok) return; // if the external call failed for this actor, skip (admissible domain still wide)

        // exactly one assertion: depositsCount == before + 1
        uint256 after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

