pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // Fuzzed params: amount to fund c, and a flag to decide whether attacker should be used.
    function testFuzz_property(uint256 fundAmount, bool useAttacker) public {
        // keep fundAmount in a reasonable wide range but non-zero
        fundAmount = bound(fundAmount, 0, 1 ether);

        address payer = address(0xBEEF);
        vm.deal(payer, 1 ether);

        // fund contract c from an EOA
        vm.prank(payer);
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        // optionally deploy attacker that will re-enter via receive when owner is sent funds
        if (useAttacker) {
            attacker = new Attacker(c);
