    C c;
    address owner = address(0xABCD);

    function setUp() public { c = new C(); }

    // fuzz amount: how much to deposit then withdraw
    function testFuzz_property(uint256 amount) public {
        // keep amount in a practical range to avoid overflows in test environment
        amount = bound(amount, 1, 1 ether);

        // fund the owner EOA so it can send and receive
        vm.deal(owner, 2 ether);

        // owner sends amount to contract via receive()
        vm.prank(owner);
        (bool sent,) = address(c).call{value: amount}(""");
        require(sent, "deposit failed in test setup");

        // sanity: contract should now have 'amount' balance
        // Now call withdraw as the owner
        vm.prank(owner);
        // call withdraw(amount) and ignore revert semantics — we capture final balance
        try c.withdraw(amount) {
            // do nothing
        } catch {
            // if it reverts, that's allowed; we'll assert based on balance change
        }

        // Single assertion: in the correct contract, after owner withdraw(amount) the contract balance is strictly less than before (i.e., decreased by amount)
        // Read contract balance via address(c).balance
        assertTrue(address(c).balance < amount, "contract balance did not decrease after withdraw");
    }
}

