pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the withdraw amount and an address that will act as owner
    function testFuzz_property(uint256 amount, address possibleOwner) public {
        // Keep domain wide but ensure a valid EOA-like owner candidate (non-zero)
        vm.assume(possibleOwner != address(0));

        // Make possibleOwner the owner by deploying a fresh C as setUp did (owner is deployer)
        // We need possibleOwner to be the owner of the existing c. To achieve this, we impersonate the deployer
        // when creating c is not possible here (setUp already deployed). Instead, we will transfer ownership-like control
        // by making possibleOwner be the msg.sender for withdraw calls via vm.prank. The contract C uses msg.sender==owner
        // where owner was set at deployment to address(this) in setUp (the test contract). To satisfy the universal property
        // without changing C, we instead perform deposits from the test contract (which is owner) and then call withdraw
        // as the owner (the test contract). The fuzzed address will be used as the recipient of a low-level call inside sendMoney
        // to ensure we use a fuzzed input. However, the property of interest is balance change on withdraw invoked by owner.

        // Bound amount to a reasonable range so vm.deal won't overflow or be trivially zero-only; keep zero allowed.
        uint256 boundedAmount = amount % (1 ether * 1000);

        // Fund the contract c with some ether from this test contract (which is the owner of c)
        uint256 initialFund = boundedAmount + 1 ether; // ensure we can withdraw boundedAmount
        vm.deal(address(this), initialFund);
        // send funds to c
        payable(address(c)).transfer(initialFund);

        // Record balance before withdraw
        uint256 balBefore = address(c).balance;

        // Call withdraw as the owner (this test contract is the owner because it deployed c in setUp)
        // Use try/catch to capture any revert; but we expect no revert in reference
        bool ok;
        try c.withdraw(boundedAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: for the correct contract, if the owner calls withdraw(amount) and the contract had >= amount,
        // the contract balance decreases by exactly amount (withdraw forwarded the funds). The buggy mutant that
        // commented out transfer will leave the contract balance unchanged for some inputs; thus there exist inputs
        // where balAfter == balBefore even though withdraw was called successfully.
        // We assert the universal property: if the call succeeded and balBefore >= boundedAmount then balBefore - balAfter == boundedAmount.
        // This reads c via address(c).balance and is a single assertTrue as required.
        if (ok && balBefore >= boundedAmount) {
            assertTrue(balBefore - balAfter == boundedAmount);
        }
    }
}

