pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the amount to send and a boolean choose which helper to use
    function testFuzz_property(uint256 amount, bool useReverter) public {
        // keep amount within contract balanceable bounds
        amount = bound(amount, 0, 1 ether);

        // fund the contract with enough balance so sendMoney can forward value
        vm.deal(address(this), 2 ether);
        // send some ETH into c so c has balance to forward
        payable(address(c)).transfer(1 ether);

        // deploy adversarial helper based on the fuzzed choice
        address target;
        if (useReverter) {
            // a callee that always reverts on receive/fallback
            Reverter r = new Reverter();
            target = address(r);
        } else {
            // a callee that accepts funds and does nothing
            Receiver r2 = new Receiver();
            target = address(r2);
        }

        // now call sendMoney from the contract owner (setUp deployer is owner)
        bool ok;
        try c.sendMoney(target, amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: the reference implementation C never reverts when sendMoney is called
        // (it ignores the callee's failure). Thus for ALL inputs ok must be true on the reference.
        // The mutant that requires success will make ok==false for at least some inputs (when useReverter==true && amount<=c.balance).
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Receiver {
    event Received(address, uint256);
    fallback() external payable {
        emit Received(msg.sender, msg.value);
    }
    receive() external payable {
        emit Received(msg.sender, msg.value);
    }
}
